1089		if err != nil || len(list) != 1 {
1090			t.Fatalf("reopened list = %+v err=%v", list, err)
1091		}
1092		if list[0].Status != StatusVoided || list[0].VoidReason != "复测" || len(list[0].Results) != 1 {
1093			t.Fatalf("reopened sample wrong: %+v", list[0])
1094		}
1095		if _, err := s2.RegisterPoint("P1", "再试"); !errors.Is(err, ErrDuplicatePoint) {
