79	// 只登记了一组限值时，另一组的样品必须因缺适用上限拒绝确认：
80	// 保持待判定、不留部分结果、不借用另一组的限值。
81	func TestLimitGroupMissingLimit(t *testing.T) {
82		s, _ := open(t)
83		zeroPoint := "P\x00A"
84		zeroItem := "A\x00B"
85		mustPoint(t, s, zeroPoint, "带零编号")
86		mustPoint(t, s, "P", "普通编号")
87		mustLimit(t, s, zeroPoint, "B", 10, at(1, 0))
